INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(1,'Lemon Caper Chicken','Chicken','Italian','Activation',152,25,3,7,'100g raw chicken breast||30ml lemon juice||50ml chicken broth||10g capers||80g zucchini||5g fresh parsley||2g garlic','Season chicken breast with garlic and herbs.||Sear chicken in a non-stick pan with a splash of chicken broth until golden.||Add remaining broth, lemon juice, and capers to the pan.||Add sliced zucchini and simmer covered until chicken is cooked through and zucchini is tender.||Garnish with fresh parsley and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(2,'Light Chicken Cacciatore','Chicken','Italian','Activation',165,26,3,9,'100g raw chicken breast||80g canned crushed tomatoes||40g mushrooms||30g bell pepper||40ml vegetable broth||2g garlic||3g fresh rosemary','Slice chicken breast into bite-sized pieces and season with rosemary and minced garlic.||Brown chicken in a hot non-stick skillet using a splash of vegetable broth.||Add mushrooms and bell peppers, sautéing until soft.||Stir in crushed tomatoes and remaining broth.||Simmer on low heat for 10 minutes until reduced and rich, then serve.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(3,'Balsamic Chicken with Spinach','Chicken','Italian','Activation',158,25,3,7,'100g raw chicken breast||15ml balsamic vinegar||60g fresh spinach||40g cherry tomatoes||50ml chicken broth||2g garlic||2g basil','Season chicken breast with garlic and basil.||Sear chicken in a non-stick pan with a splash of chicken broth until browned.||Pour in balsamic vinegar and remaining broth, reducing to a glossy glaze.||Toss in cherry tomatoes and fresh spinach, cooking just until wilted.||Plate chicken and spoon the wilted greens and glaze over top.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(4,'Herb-Roasted Chicken with Eggplant','Chicken','Italian','Activation',154,24,3,8,'100g raw chicken breast||90g eggplant||40g zucchini||40ml vegetable broth||5g fresh oregano||2g garlic||10ml lemon juice','Toss cubed eggplant and sliced zucchini with minced garlic and oregano.||Roast vegetables in a non-stick pan with a splash of vegetable broth until tender and caramelized.||Season chicken breast and sear in the same pan alongside the vegetables.||Drizzle lemon juice over the chicken and vegetables just before finishing.||Serve warm together.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(5,'Garlic Chicken with Broccolini','Chicken','Italian','Activation',162,27,3,8,'100g raw chicken breast||100g broccolini||3g garlic||50ml chicken broth||15ml lemon juice||2g red pepper flakes','Sauté sliced garlic and red pepper flakes in a non-stick pan with a splash of chicken broth until fragrant.||Add broccolini and remaining broth, covering to steam until tender-crisp.||Push broccolini aside and sear the seasoned chicken breast in the pan until fully cooked.||Stir in lemon juice to glaze the pan, coating chicken and broccolini.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(6,'Chicken Puttanesca','Chicken','Italian','Activation',163,24,5,6,'100g raw chicken breast||70g canned crushed tomatoes||10g capers||15g black olives||30ml vegetable broth||2g garlic||3g fresh parsley','Season chicken breast with minced garlic and sear in a hot non-stick pan with a splash of vegetable broth.||Add crushed tomatoes, capers, and sliced black olives to the pan.||Simmer uncovered for 8-10 minutes until the sauce thickens and chicken is cooked through.||Garnish with fresh parsley and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(7,'Chicken with Mushrooms and Thyme','Chicken','Italian','Activation',157,27,3,6,'100g raw chicken breast||90g white mushrooms||50g fresh spinach||40ml chicken broth||2g garlic||3g fresh thyme||10ml lemon juice','Slice mushrooms and sauté in a non-stick pan with minced garlic, fresh thyme, and a splash of chicken broth until browned.||Push mushrooms aside and add the seasoned chicken breast, searing on both sides.||Add remaining broth and fresh spinach, covering until spinach wilts and chicken is cooked through.||Drizzle with lemon juice before serving.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(8,'Light Beef Pizzaiola','Beef','Italian','Activation',177,25,4,10,'100g raw extra lean beef round steak||70g canned crushed tomatoes||50g zucchini||30g white mushrooms||30ml vegetable broth||2g garlic||3g fresh oregano','Season beef round steak with minced garlic and oregano.||Sear beef in a hot non-stick pan using a splash of vegetable broth until browned on both sides.||Add sliced zucchini and mushrooms to the pan, sautéing briefly.||Pour in crushed tomatoes and remaining broth, simmering covered for 8-10 minutes until beef is tender and sauce reduces.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(9,'Light Meatballs in Tomato Sauce','Beef','Italian','Activation',179,23,5,9,'100g raw extra lean ground beef||80g canned crushed tomatoes||40g fresh spinach||30ml vegetable broth||2g garlic||2g fresh basil','Form extra lean ground beef into small meatballs mixed with minced garlic and basil.||Brown meatballs in a non-stick skillet with a splash of vegetable broth.||Pour in crushed tomatoes and remaining broth, simmering gently for 10 minutes.||Toss in fresh spinach during the last two minutes until wilted.||Serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(10,'Beef and Mushroom Stew','Beef','Italian','Activation',173,25,4,6,'100g raw lean beef chuck||80g white mushrooms||40g bell pepper||40ml beef broth||2g garlic||3g fresh rosemary','Season cubed lean beef with minced garlic and fresh rosemary.||Sear beef in a hot non-stick pan with a splash of beef broth until browned.||Add sliced mushrooms and diced bell peppers, sautéing until tender.||Add remaining beef broth, cover, and simmer on low heat for 15 minutes until beef is tender.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(11,'Warm Beef Carpaccio with Eggplant','Beef','Italian','Activation',164,23,4,8,'100g raw lean beef sirloin||90g eggplant||40ml vegetable broth||15ml lemon juice||5g fresh parsley||2g garlic','Sauté diced eggplant with minced garlic and a splash of vegetable broth in a non-stick pan until soft and caramelized.||Push eggplant to the side and quickly flash-sear the thinly sliced lean beef for 30 seconds per side.||Drizzle with fresh lemon juice and toss gently.||Garnish with fresh parsley and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(12,'Light Beef Bolognese','Beef','Italian','Activation',179,23,5,9,'100g raw extra lean ground beef||70g canned crushed tomatoes||40g zucchini||30g celery||40ml vegetable broth||2g garlic||2g fresh basil','Dry-sauté extra lean ground beef in a non-stick pan until browned, breaking it apart.||Add minced celery, diced zucchini, and garlic along with a splash of vegetable broth, cooking until soft.||Stir in crushed tomatoes and fresh basil.||Simmer uncovered for 10 minutes until reduced into a rich meat sauce, then serve.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(13,'Beef with Zucchini and Capers','Beef','Italian','Activation',159,23,4,6,'100g raw lean beef round steak||100g zucchini||10g capers||40ml vegetable broth||10ml lemon juice||2g garlic||3g fresh parsley','Sauté sliced zucchini and minced garlic in a non-stick pan with a splash of vegetable broth until tender-crisp.||Push zucchini aside and sear the sliced lean beef round steak until browned.||Add capers, lemon juice, and remaining broth, simmering for 3 minutes until glaze forms.||Garnish with fresh parsley and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(14,'Beef Strips with Spinach and Cherry Tomatoes','Beef','Italian','Activation',160,25,4,5,'100g raw lean beef sirloin||60g fresh spinach||50g cherry tomatoes||40ml beef broth||2g garlic||3g fresh oregano','Season beef sirloin strips with garlic and oregano.||Sear beef strips in a hot non-stick pan with a splash of beef broth for 2 minutes.||Toss in halved cherry tomatoes and fresh spinach, stirring until tomatoes soften and spinach wilts.||Add remaining broth to tie the juices together and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(15,'Cod in Light Tomato Broth (Acqua Pazza)','Fish','Italian','Activation',107,19,1,5,'100g raw cod fillet||60g cherry tomatoes||30g celery||50ml vegetable broth||10ml lemon juice||2g garlic||3g fresh parsley','Sauté minced garlic and sliced celery in a non-stick pan with a splash of vegetable broth until soft.||Add halved cherry tomatoes, cod fillet, and remaining vegetable broth to the pan.||Cover and simmer gently for 6-8 minutes until the fish is cooked through and flaky.||Drizzle with lemon juice, garnish with fresh parsley, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(16,'Baked Cod Parcel with Zucchini','Fish','Italian','Activation',114,21,1,5,'100g raw cod fillet||80g zucchini||40g cherry tomatoes||40ml fish broth||10ml lemon juice||2g garlic||3g fresh thyme','Place the cod fillet in the center of a parchment paper sheet, surrounded by sliced zucchini and cherry tomatoes.||Season with minced garlic, fresh thyme, a splash of fish broth, and lemon juice.||Seal the parchment paper tightly into a packet and bake at 180°C for 15 minutes.||Open carefully and serve warm in its parchment pouch.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(17,'Light Cod alla Livornese','Fish','Italian','Activation',124,19,3,4,'100g raw cod fillet||70g canned crushed tomatoes||10g capers||15g black olives||30ml vegetable broth||2g garlic||3g fresh parsley','Sauté minced garlic in a non-stick skillet with a splash of vegetable broth.||Stir in canned crushed tomatoes, capers, and sliced black olives, simmering for 5 minutes.||Nestle the cod fillet into the rich tomato sauce, cover, and simmer for 8 minutes until cooked.||Garnish with fresh parsley and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(18,'Sea Bass with Eggplant Cream','Fish','Italian','Activation',126,20,2,6,'100g raw sea bass fillet||90g eggplant||40ml vegetable broth||10ml lemon juice||2g garlic||3g fresh basil','Cube eggplant and sauté in a non-stick pan with minced garlic and vegetable broth until completely soft.||Blend or mash the cooked eggplant with fresh basil and lemon juice into a smooth cream.||Sear the sea bass fillet in a clean non-stick pan with a splash of broth until crisp on the skin side and cooked through.||Spread the warm eggplant cream on the plate and top with the sea bass.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(19,'Cod with Mushrooms and Spinach','Fish','Italian','Activation',117,22,1,5,'100g raw cod fillet||70g white mushrooms||50g fresh spinach||40ml vegetable broth||2g garlic||3g fresh thyme||10ml lemon juice','Sauté sliced white mushrooms and minced garlic in a non-stick pan with a splash of vegetable broth until browned.||Add fresh spinach and remaining broth, stirring until the spinach wilts.||Push the vegetables aside and sear the cod fillet in the same pan for 3 minutes per side until flaky.||Drizzle with lemon juice and serve hot together.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(20,'Lemon Cod with Broccolini and Capers','Fish','Italian','Activation',125,22,1,7,'100g raw cod fillet||90g broccolini||10g capers||40ml vegetable broth||15ml lemon juice||2g garlic||2g red pepper flakes','Sauté minced garlic and red pepper flakes in a non-stick pan with a splash of vegetable broth.||Add broccolini and remaining broth, covering to steam until tender-crisp.||Add the cod fillet, capers, and fresh lemon juice to the pan, covering and simmering for 6 minutes until the fish is opaque.||Serve warm with the citrus reduction pan juices.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(21,'Light Cod alla Sorrentina','Fish','Italian','Activation',118,19,1,5,'100g raw cod fillet||70g canned crushed tomatoes||40g bell pepper||30ml vegetable broth||2g garlic||3g fresh oregano','Sauté diced bell peppers and minced garlic in a non-stick pan with a splash of vegetable broth until soft.||Pour in crushed tomatoes and fresh oregano, letting the mixture simmer for 5 minutes.||Place the cod fillet into the simmering sauce, cover, and cook gently for 8 minutes until flaky and fully cooked.||Serve hot, spooning the rich sauce over the fish.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(22,'Light Pork Pizzaiola','Pork (lean','Italian','Activation',168,25,4,7,'100g raw lean pork tenderloin||70g canned crushed tomatoes||50g zucchini||30ml vegetable broth||2g garlic||3g fresh oregano','Season lean pork tenderloin medallions with minced garlic and fresh oregano.||Sear the pork medallions in a hot non-stick skillet using a splash of vegetable broth until browned on both sides.||Add sliced zucchini to the pan and sauté briefly.||Pour in crushed tomatoes and remaining broth, cover, and simmer for 8-10 minutes until the pork is tender and the sauce reduces.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(23,'Pork and Mushroom Stew with Thyme','Pork (lean','Italian','Activation',166,26,4,6,'100g raw lean pork tenderloin||80g white mushrooms||40g bell pepper||40ml vegetable broth||2g garlic||3g fresh thyme','Cut lean pork tenderloin into bite-sized cubes and season with minced garlic and fresh thyme.||Brown the pork cubes in a hot non-stick pan with a splash of vegetable broth.||Add sliced white mushrooms and diced bell peppers, sautéing until soft.||Pour in remaining broth, cover, and simmer on low heat for 12 minutes until the pork is fully cooked and tender.||Serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(24,'Lemon Caper Pork Loin','Pork (lean','Italian','Activation',152,24,3,5,'100g raw lean pork tenderloin||100g zucchini||10g capers||40ml vegetable broth||15ml lemon juice||2g garlic||3g fresh parsley','Sauté sliced zucchini and minced garlic in a non-stick pan with a splash of vegetable broth until tender-crisp.||Push the zucchini aside and sear the seasoned lean pork tenderloin medallions until golden and cooked through.||Add capers, lemon juice, and remaining broth to the pan, simmering for 2 minutes to create a light pan-sauce.||Garnish with fresh parsley and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(25,'Pork Cacciatore with Spinach','Pork (lean','Italian','Activation',165,25,4,8,'100g raw lean pork tenderloin||80g canned crushed tomatoes||40g fresh spinach||30ml vegetable broth||2g garlic||3g fresh rosemary','Brown lean pork tenderloin medallions in a non-stick pan with a splash of vegetable broth and minced garlic.||Stir in crushed tomatoes and fresh rosemary, simmering gently for 8 minutes.||Toss in fresh spinach during the final two minutes until wilted into the sauce.||Ensure the pork is fully cooked through and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(26,'Pork Rolls with Eggplant','Pork (lean','Italian','Activation',162,24,4,7,'100g raw lean pork tenderloin||90g eggplant||40ml vegetable broth||2g garlic||3g fresh basil||10ml lemon juice','Dice eggplant finely and sauté with minced garlic and a splash of vegetable broth until completely soft, mixing in fresh basil.||Pound the lean pork tenderloin thin, spread the soft eggplant mixture over it, and roll it up securely.||Place the roll in a non-stick pan with remaining broth and bake or pan-simmer covered for 12 minutes until cooked.||Drizzle with lemon juice and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(27,'Pork Loin with Broccolini and Rosemary','Pork (lean','Italian','Activation',160,26,3,7,'100g raw lean pork tenderloin||100g broccolini||40ml vegetable broth||2g garlic||3g fresh rosemary||10ml lemon juice','Sauté minced garlic and chopped rosemary in a non-stick pan with a splash of vegetable broth.||Add broccolini and remaining broth, covering to steam until tender-crisp.||Push the broccolini aside and sear the seasoned lean pork tenderloin medallions until cooked through.||Drizzle lemon juice over the dish just before plating and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(28,'Pork Strips with Cherry Tomatoes and Basil','Pork (lean','Italian','Activation',158,25,3,6,'100g raw lean pork tenderloin||60g cherry tomatoes||50g zucchini||40ml vegetable broth||2g garlic||3g fresh basil','Slice lean pork tenderloin into thin strips and season with minced garlic.||Sear the pork strips in a hot non-stick pan with a splash of vegetable broth for 2 minutes.||Toss in halved cherry tomatoes and diced zucchini, stirring until the vegetables soften and release their juices.||Stir in fresh basil and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(29,'Steamed Chicken with Ginger and Scallion','Chicken','Chinese','Activation',190,33,4,4,'100g raw chicken breast||80g napa cabbage||40g mung bean sprouts||20ml chicken broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||3g scallions','Slice chicken breast and marinate with shaoxing wine and minced ginger.||Arrange napa cabbage and bean sprouts in a steaming dish, placing the chicken on top.||Pour chicken broth and light soy sauce over the mixture.||Steam over high heat for 12 minutes until chicken is cooked through.||Garnish with fresh scallions and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(30,'Spicy Sichuan Chicken Soup with Wood Ear Mushrooms','Chicken','Chinese','Activation',185,32,4,6,'100g raw chicken breast||60g wood ear mushrooms||50g bok choy||50ml chicken broth||10ml light soy sauce||5ml Chinese black vinegar||2g garlic||2g Sichuan peppercorns','Bring chicken broth, crushed garlic, and Sichuan peppercorns to a simmer in a non-stick pot.||Add sliced chicken breast and rehydrated wood ear mushrooms, cooking for 5 minutes.||Stir in chopped bok choy and simmer for another 3 minutes until tender.||Remove from heat, stir in black vinegar and light soy sauce, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(31,'Chicken with Shiitake and Bean Sprouts','Chicken','Chinese','Activation',195,33,4,7,'100g raw chicken breast||70g fresh shiitake mushrooms||60g mung bean sprouts||30ml chicken broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||2g garlic','Slice chicken breast and marinate with a splash of shaoxing wine and minced garlic.||Heat chicken broth in a hot non-stick pan, then add sliced shiitake mushrooms and ginger, cooking until soft.||Add the chicken strips and water-stir-fry until the chicken begins to turn white.||Toss in mung bean sprouts and light soy sauce, stirring briskly for 2 minutes until sprouts are tender-crisp.||Serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(32,'Braised Chicken with Bamboo Shoots and Star Anise','Chicken','Chinese','Activation',190,32,4,6,'100g raw chicken breast||70g canned bamboo shoots||60g bok choy||50ml chicken broth||10ml light soy sauce||5ml shaoxing wine||2g star anise||3g fresh ginger','Combine chicken broth, light soy sauce, shaoxing wine, star anise, and sliced ginger in a pot.||Add cubed chicken breast and sliced bamboo shoots, bringing to a gentle simmer.||Cover and simmer for 10 minutes until the chicken absorbs the aromatic flavors.||Add chopped bok choy during the final 3 minutes until wilted.||Discard star anise and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(33,'Hunan Chicken with Celery and Napa Cabbage','Chicken','Chinese','Activation',190,32,4,7,'100g raw chicken breast||80g napa cabbage||40g celery||40ml chicken broth||10ml light soy sauce||5ml Chinese black vinegar||3g garlic||2g red pepper flakes','Slice chicken breast into thin strips and marinate with minced garlic and red pepper flakes.||Place chicken in a hot non-stick pan with a splash of chicken broth, searing until lightly browned.||Add sliced celery and chopped napa cabbage along with remaining broth and light soy sauce.||Cover and simmer for 6 minutes until vegetables are tender and broth reduces into a savory glaze.||Stir in black vinegar and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(34,'Cantonese Poached Chicken with Choy Sum','Chicken','Chinese','Activation',185,32,4,5,'100g raw chicken breast||90g choy sum||40ml chicken broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||2g scallions','Bring chicken broth, sliced ginger, and shaoxing wine to a boil in a shallow pan.||Submerge the whole chicken breast, cover, and poach gently on low heat for 8-10 minutes.||Add choy sum to the broth alongside the chicken for the last 4 minutes until tender-crisp.||Remove chicken, slice, and arrange over the choy sum.||Drizzle with light soy sauce and garnish with fresh scallions.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(35,'Spicy Garlic Chicken with Wood Ear and Bean Sprouts','Chicken','Chinese','Activation',190,33,4,6,'100g raw chicken breast||50g wood ear mushrooms||60g mung bean sprouts||40ml chicken broth||10ml light soy sauce||5ml Chinese black vinegar||3g garlic||2g chili flakes','Mince garlic and combine with chili flakes, chicken broth, and light soy sauce in a non-stick pan.||Add sliced chicken breast and rehydrated wood ear mushrooms, cooking over medium heat for 5 minutes.||Toss in mung bean sprouts and stir-fry in the reducing sauce for 2 minutes until tender-crisp.||Remove from heat, drizzle with black vinegar, and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(36,'Light Coconut Chili Chicken (Masak Lemak)','Chicken','Malay','Activation',165,31,4,4,'100g raw chicken breast||60g long beans||40g eggplant||40ml light coconut milk||20ml water||3g fresh turmeric root||5g bird eye chili||2g lemongrass','Blend fresh turmeric, bird eye chili, and lemongrass into a fine paste.||Combine the spice paste, light coconut milk, and water in a non-stick pot, bringing to a gentle simmer.||Add cubed chicken breast, sliced long beans, and diced eggplant to the simmering spiced broth.||Cook uncovered for 10-12 minutes, stirring occasionally, until the chicken is cooked through and vegetables are tender.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(37,'Spicy Turmeric Grilled Chicken (Ayam Percik)','Chicken','Malay','Activation',158,32,3,5,'100g raw chicken breast||80g bok choy||30ml water||15ml tamarind juice||3g fresh ginger||5g shallots||4g bird eye chili||2g lemongrass','Blend shallots, ginger, lemongrass, and bird eye chili into a smooth paste.||Mix the spice paste with tamarind juice and water to create a marinade.||Coat the chicken breast with the mixture and marinate for 15 minutes.||Place the chicken and remaining sauce in a non-stick pan, adding chopped bok choy around it.||Cover and simmer on medium heat for 12 minutes until the sauce reduces to a glaze and chicken is fully cooked.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(38,'Chicken in Spicy Tamarind Broth (Asam Pedas)','Chicken','Malay','Activation',154,32,2,6,'100g raw chicken breast||70g okra||40g tomato||40ml water||15ml tamarind juice||3g fresh ginger||5g shallots||3g dried chili paste','Blend shallots, ginger, and dried chili paste into a spice paste.||In a pot, combine the spice paste with water and tamarind juice, bringing to a boil.||Add sliced chicken breast and whole okra pods to the sour and spicy broth.||Simmer gently for 10 minutes until the chicken is tender and the okra is cooked through.||Serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(39,'Dry Minangkabau Chicken Rendang','Chicken','Malay','Activation',172,32,5,6,'100g raw chicken breast||60g long beans||30ml light coconut milk||20ml water||5g shallots||3g fresh galangal||3g lemongrass||4g unsweetened desiccated coconut','Toast desiccated coconut in a dry pan until golden brown, then grind into a paste.||Blend shallots, galangal, and lemongrass into a fine spice paste.||Combine spice paste, toasted coconut paste, light coconut milk, and water in a non-stick pan.||Add chicken breast and sliced long beans, simmering on low heat until the liquid completely reduces and coats the chicken.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(40,'Spiced Chicken and Bone Soup','Chicken','Malay','Activation',150,32,3,4,'100g raw chicken breast||80g napa cabbage||40g celery||60ml water||3g fresh ginger||2g garlic||2g cinnamon stick||3g star anise','Bring water to a boil with crushed garlic, ginger, cinnamon stick, and star anise to form a spiced broth.||Add sliced chicken breast, chopped celery, and napa cabbage to the pot.||Simmer covered on medium heat for 10 minutes until the chicken is tender and flavors infuse the broth.||Remove cinnamon stick and star anise, then serve hot as a clear, aromatic soup.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(41,'Oil-Free Spiced Chicken (Ayam Berempah)','Chicken','Malay','Activation',160,33,3,5,'100g raw chicken breast||80g cucumber slices||15ml water||3g fresh turmeric root||5g shallots||3g lemongrass||2g ground coriander||2g cumin powder','Blend turmeric, shallots, lemongrass, ground coriander, and cumin with a splash of water into a thick spice paste.||Coat the chicken breast thoroughly with the spice paste and let marinate for 20 minutes.||Place the coated chicken in a hot non-stick pan with a few drops of water, covering with a lid to steam-roast for 6 minutes.||Remove the lid and sear until the spices form a dry, fragrant crust on the chicken.||Serve alongside fresh cucumber slices.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(42,'Ginger and Chili Chicken','Chicken','Malay','Activation',155,32,3,4,'100g raw chicken breast||70g bok choy||40ml water||10ml light soy sauce||10g fresh ginger||3g garlic||5g scallions','Slice chicken breast and julienne a generous amount of fresh ginger.||Sauté minced garlic and ginger in a non-stick pan with a splash of water until fragrant.||Add chicken strips, light soy sauce, and remaining water, cooking until the chicken turns white.||Toss in chopped bok choy and scallions, covering for 3 minutes until tender.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(43,'Thai Basil Chicken (Pad Kaphrao)','Chicken','Thai','Activation',168,33,3,5,'100g raw chicken breast||80g Thai holy basil leaves||40g green beans||30ml water||10ml light soy sauce||5ml fish sauce||5g bird eye chili||2g garlic','Mince garlic and bird eye chili together, then dry-sauté in a hot non-stick pan with a splash of water until fragrant.||Add finely diced chicken breast and stir-fry until completely white and cooked through.||Stir in light soy sauce, fish sauce, and sliced green beans, tossing for 2 minutes.||Turn off the heat, fold in the fresh Thai holy basil leaves until wilted from residual heat, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(44,'Clear Tom Yum Chicken Soup','Chicken','Thai','Activation',155,32,3,4,'100g raw chicken breast||70g straw mushrooms||40g bok choy||80ml water||10ml lime juice||5ml fish sauce||5g galangal||3g lemongrass||3g kaffir lime leaves||5g Thai chili paste','Bring water to a boil in a pot with sliced galangal, bruised lemongrass, and torn kaffir lime leaves.||Add sliced chicken breast and straw mushrooms, simmering for 6 minutes until tender.||Stir in Thai chili paste and fish sauce, cooking for another minute.||Remove from heat, stir in fresh lime juice and chopped bok choy, and serve hot as a clear soup.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(45,'Ginger Chicken Stir (Phad King)','Chicken','Thai','Activation',162,33,3,6,'100g raw chicken breast||70g fresh ginger||50g wood ear mushrooms||30ml water||10ml light soy sauce||5ml fish sauce||3g garlic||5g scallions','Julienne fresh ginger and slice wood ear mushrooms.||Sauté minced garlic and ginger in a non-stick pan with a splash of water until aromatic.||Add sliced chicken breast and stir-fry until it begins to turn white.||Toss in wood ear mushrooms, light soy sauce, fish sauce, and remaining water, simmering for 4 minutes until tender.||Garnish with fresh scallions and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(46,'Grilled Chicken with Jaew Dipping Sauce','Chicken','Thai','Activation',159,32,3,4,'100g raw chicken breast||80g cucumber slices||15ml water||10ml lime juice||5ml fish sauce||3g shallots||4g toasted ground rice||3g dried chili flakes','Marinate chicken breast with a splash of fish sauce and water, then grill or pan-sear in a non-stick pan until fully cooked and lightly charred.||Prepare the dipping sauce by mixing lime juice, fish sauce, finely diced shallots, toasted ground rice, and dried chili flakes.||Slice the cooked chicken and serve immediately alongside fresh cucumber slices with the dipping sauce on the side.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(47,'Chicken Jungle Curry (Gaeng Pa)','Chicken','Thai','Activation',164,32,4,7,'100g raw chicken breast||60g eggplant||50g green beans||50ml water||10ml fish sauce||5g Thai red curry paste||3g galangal||3g kaffir lime leaves','Dissolve Thai red curry paste in a non-stick pan with a splash of water, simmering until fragrant.||Add cubed chicken breast, diced eggplant, and sliced green beans to the pan.||Pour in remaining water, adding bruised galangal and torn kaffir lime leaves.||Simmer uncovered for 10-12 minutes until the vegetables are tender and the chicken is fully cooked.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(48,'Chicken with Curry Paste and Long Beans (Prik King)','Chicken','Thai','Activation',163,33,3,6,'100g raw chicken breast||90g green beans||30ml water||10ml fish sauce||5ml light soy sauce||6g Thai red curry paste||3g kaffir lime leaves','Dry-sauté Thai red curry paste in a non-stick pan with a splash of water until aromatic.||Add sliced chicken breast and stir-fry until coated and partially cooked.||Add sliced green beans, fish sauce, light soy sauce, and remaining water.||Toss and simmer for 5 minutes until the beans are tender-crisp and coated in a reduced savory glaze.||Garnish with finely shredded kaffir lime leaves and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(49,'Chinese Beef with Zucchini and Capers','Beef (lean)','Chinese','Activation',183,27,5,7,'100g raw lean beef sirloin||80g zucchini||40g bok choy||40ml beef broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||2g garlic','Slice lean beef sirloin thinly and marinate with shaoxing wine and minced garlic.||Heat beef broth in a non-stick wok, then add sliced ginger and bok choy, cooking until tender.||Add the marinated beef slices and stir-fry until they change color.||Toss in sliced zucchini and light soy sauce, simmering for 2 minutes until the vegetables are tender-crisp.||Serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(50,'Beef with Sauteed Greens (Chao Qing Cai)','Beef (lean)','Chinese','Activation',180,27,5,6,'100g raw lean beef round steak||90g napa cabbage||30g celery||40ml beef broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||2g garlic','Slice beef round steak into thin strips and marinate with a splash of shaoxing wine and minced garlic.||Bring beef broth to a simmer in a non-stick pan, adding julienned ginger, chopped celery, and napa cabbage.||Add the beef strips and stir-fry in the simmering broth until cooked through.||Stir in light soy sauce and toss until the vegetables are tender and the sauce is reduced.||Serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(51,'Beef with Shiitake and Bok Choy','Beef (lean)','Chinese','Activation',185,28,5,7,'100g raw lean beef chuck||70g fresh shiitake mushrooms||60g bok choy||50ml beef broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||2g garlic','Slice lean beef chuck and fresh shiitake mushrooms.||Combine beef broth, light soy sauce, shaoxing wine, and minced garlic in a non-stick wok.||Add the beef and shiitake mushrooms, bringing to a simmer for 5 minutes until the beef is tender.||Toss in chopped bok choy and cook for another 3 minutes until wilted and incorporated.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(52,'Spiced Beef with Bean Sprouts','Beef (lean)','Chinese','Activation',178,27,5,5,'100g raw lean beef sirloin||80g mung bean sprouts||40g wood ear mushrooms||40ml beef broth||10ml light soy sauce||5ml Chinese black vinegar||3g fresh ginger||2g Sichuan peppercorns','Marinate thinly sliced beef sirloin with minced ginger and Sichuan peppercorns.||Bring beef broth and light soy sauce to a boil in a non-stick pan.||Add rehydrated wood ear mushrooms and beef slices, cooking for 3 minutes.||Toss in mung bean sprouts and stir-fry for 2 minutes until tender-crisp.||Remove from heat, drizzle with black vinegar, and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(53,'Garlic Beef with Chinese Broccoli','Beef (lean)','Chinese','Activation',181,28,5,6,'100g raw lean beef round steak||90g gai lan (chinese broccoli)||40ml beef broth||10ml light soy sauce||5ml shaoxing wine||3g fresh ginger||3g garlic','Slice lean beef round steak thinly and chop gai lan into manageable lengths.||Sauté minced garlic and ginger in a non-stick wok with a splash of beef broth until aromatic.||Add the gai lan and remaining broth, covering to steam for 3 minutes.||Push the greens aside, add the beef and shaoxing wine, and stir-fry until the beef is cooked through.||Stir in light soy sauce and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(54,'Grilled Beef Salad (Nam Tok)','Beef (lean)','Thai','Activation',185,28,5,6,'100g raw lean beef sirloin||80g cucumber slices||40g bok choy||20ml water||10ml lime juice||10ml fish sauce||3g shallots||4g toasted ground rice||3g dried chili flakes','Grill or pan-sear the lean beef sirloin in a hot non-stick pan with a splash of water until medium-rare, then slice thinly.||In a bowl, toss the sliced beef with fresh lime juice, fish sauce, thinly sliced shallots, toasted ground rice, and dried chili flakes.||Serve the warm beef salad immediately alongside fresh cucumber slices and raw bok choy.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(55,'Thai Basil Beef (Pad Kaphrao)','Beef (lean)','Thai','Activation',189,28,5,6,'100g raw lean beef round steak||70g Thai holy basil leaves||50g green beans||30ml water||10ml fish sauce||10ml light soy sauce||5g bird eye chili||2g garlic','Mince garlic and bird eye chili together, then dry-sauté in a hot non-stick pan with a splash of water until aromatic.||Add finely minced or chopped lean beef round steak and stir-fry until completely cooked through.||Stir in fish sauce, light soy sauce, and sliced green beans, tossing for 2 minutes.||Turn off the heat, fold in the fresh Thai holy basil leaves until wilted, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(56,'Thai Beef Salad (Yam Neua)','Beef (lean)','Thai','Activation',182,28,5,7,'100g raw lean beef sirloin||60g cucumber||50g celery||20ml water||10ml lime juice||10ml fish sauce||5g shallots||3g lemongrass||4g Thai chili paste','Pan-sear the lean beef sirloin in a non-stick pan with a splash of water until cooked to preference, then slice into thin strips.||Prepare the dressing by whisking together lime juice, fish sauce, and Thai chili paste.||Toss the sliced beef with thinly sliced cucumbers, crisp celery, shallots, and bruised lemongrass.||Pour the dressing over the top, mix well, and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(57,'Beef Jungle Curry (Gaeng Pa)','Beef (lean)','Thai','Activation',186,27,5,7,'100g raw lean beef chuck||60g eggplant||50g green beans||50ml water||10ml fish sauce||5g Thai red curry paste||3g galangal||3g kaffir lime leaves','Dissolve Thai red curry paste in a non-stick pan with a splash of water, simmering until fragrant.||Add cubed lean beef chuck, diced eggplant, and sliced green beans to the pan.||Pour in remaining water, adding bruised galangal and torn kaffir lime leaves.||Simmer uncovered for 12-15 minutes until the beef is tender and the vegetables absorb the spiced broth.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(58,'Beef with Curry Paste and Long Beans (Prik King)','Beef (lean)','Thai','Activation',188,28,5,6,'100g raw lean beef sirloin||90g green beans||30ml water||10ml fish sauce||5ml light soy sauce||6g Thai red curry paste||3g kaffir lime leaves','Dry-sauté Thai red curry paste in a non-stick pan with a splash of water until vibrant and aromatic.||Add thinly sliced lean beef sirloin and stir-fry until coated and partially cooked.||Add sliced green beans, fish sauce, light soy sauce, and remaining water.||Simmer for 5 minutes until the beans are tender-crisp and coated in a concentrated savory reduction.||Garnish with shredded kaffir lime leaves and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(59,'Clear Tom Yum Beef Soup','Beef (lean)','Thai','Activation',179,28,4,5,'100g raw lean beef round steak||70g straw mushrooms||40g bok choy||80ml water||10ml lime juice||5ml fish sauce||5g galangal||3g lemongrass||3g kaffir lime leaves||4g Thai chili paste','Bring water to a boil in a pot with sliced galangal, bruised lemongrass, and torn kaffir lime leaves.||Add thinly sliced lean beef round steak and straw mushrooms, simmering gently for 6 minutes.||Stir in Thai chili paste and fish sauce, cooking for another minute.||Remove from heat, stir in fresh lime juice and chopped bok choy, and serve hot as a clear, spicy broth.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(60,'Thai Basil Shrimp (Pad Kaphrao)','Shrimp','Thai','Activation',130,24,2,4,'100g raw peeled shrimp||80g Thai holy basil leaves||40g green beans||30ml water||10ml light soy sauce||5ml fish sauce||5g bird eye chili||2g garlic','Mince garlic and bird eye chili together, then dry-sauté in a hot non-stick pan with a splash of water until fragrant.||Add peeled shrimp and stir-fry until pink and opaque.||Stir in light soy sauce, fish sauce, and sliced green beans, tossing for 2 minutes.||Turn off the heat, fold in the fresh Thai holy basil leaves until wilted from residual heat, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(61,'Clear Tom Yum Shrimp Soup','Shrimp','Thai','Activation',118,24,2,4,'100g raw peeled shrimp||70g straw mushrooms||40g bok choy||80ml water||10ml lime juice||5ml fish sauce||5g galangal||3g lemongrass||3g kaffir lime leaves||5g Thai chili paste','Bring water to a boil in a pot with sliced galangal, bruised lemongrass, and torn kaffir lime leaves.||Add peeled shrimp and straw mushrooms, simmering for 4 minutes until the shrimp are cooked through.||Stir in Thai chili paste and fish sauce, cooking for another minute.||Remove from heat, stir in fresh lime juice and chopped bok choy, and serve hot as a clear soup.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(62,'Ginger Shrimp Stir (Phad King)','Shrimp','Thai','Activation',125,24,2,6,'100g raw peeled shrimp||70g fresh ginger||50g wood ear mushrooms||30ml water||10ml light soy sauce||5ml fish sauce||3g garlic||5g scallions','Julienne fresh ginger and slice wood ear mushrooms.||Sauté minced garlic and ginger in a non-stick pan with a splash of water until aromatic.||Add peeled shrimp and stir-fry until they just begin to turn pink.||Toss in wood ear mushrooms, light soy sauce, fish sauce, and remaining water, simmering for 3 minutes until tender.||Garnish with fresh scallions and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(63,'Shrimp Jungle Curry (Gaeng Pa)','Shrimp','Thai','Activation',126,24,2,7,'100g raw peeled shrimp||60g eggplant||50g green beans||50ml water||10ml fish sauce||5g Thai red curry paste||3g galangal||3g kaffir lime leaves','Dissolve Thai red curry paste in a non-stick pan with a splash of water, simmering until fragrant.||Add diced eggplant and sliced green beans to the pan along with remaining water, galangal, and kaffir lime leaves.||Simmer uncovered for 10 minutes until the vegetables are tender.||Add peeled shrimp during the final 3 minutes, cooking until pink and opaque, then serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(64,'Shrimp with Curry Paste and Long Beans (Prik King)','Shrimp','Thai','Activation',124,24,2,6,'100g raw peeled shrimp||90g green beans||30ml water||10ml fish sauce||5ml light soy sauce||6g Thai red curry paste||3g kaffir lime leaves','Dry-sauté Thai red curry paste in a non-stick pan with a splash of water until vibrant and aromatic.||Add sliced green beans, fish sauce, light soy sauce, and remaining water, simmering for 4 minutes until tender-crisp.||Add peeled shrimp to the pan and toss for 2 minutes until cooked through and coated in the reduced glaze.||Garnish with finely shredded kaffir lime leaves and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(65,'Steamed Shrimp with Glass Noodles (Goong Ob Woonsen)','Shrimp','Thai','Activation',122,24,2,5,'100g raw peeled shrimp||80g napa cabbage||40g celery||40ml water||10ml light soy sauce||5ml fish sauce||3g fresh ginger||2g garlic','Arrange chopped napa cabbage and sliced celery at the bottom of a non-stick pot with a splash of water, minced garlic, and ginger.||Place peeled shrimp on top of the vegetables.||Drizzle with light soy sauce and fish sauce, cover tightly, and steam-braise on medium heat for 6-8 minutes until the shrimp are cooked and vegetables are tender.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(66,'Thai Basil Tofu (Pad Kaphrao)','Tofu','Thai','Activation',112,11,6,5,'100g raw firm tofu||80g Thai holy basil leaves||40g green beans||30ml water||10ml natural fermented fish sauce||5g bird eye chili||2g garlic','Crumble or dice firm tofu into small pieces.||Mince garlic and bird eye chili together, then dry-sauté in a hot non-stick pan with a splash of water until aromatic.||Add the tofu and stir-fry until lightly golden.||Stir in natural fermented fish sauce and sliced green beans, tossing for 2 minutes.||Turn off the heat, fold in the fresh Thai holy basil leaves until wilted from residual heat, and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(67,'Clear Tom Yum Tofu Soup','Tofu','Thai','Activation',99,10,5,5,'100g raw firm tofu||70g straw mushrooms||40g bok choy||80ml water||10ml lime juice||5ml natural fermented fish sauce||5g galangal||3g lemongrass||3g kaffir lime leaves||5g traditional chili paste','Bring water to a boil in a pot with sliced galangal, bruised lemongrass, and torn kaffir lime leaves.||Add cubed firm tofu and straw mushrooms, simmering for 5 minutes until the tofu absorbs the aromatics.||Stir in traditional chili paste and natural fermented fish sauce, cooking for another minute.||Remove from heat, stir in fresh lime juice and chopped bok choy, and serve hot as a clear soup.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(68,'Ginger Tofu Stir (Phad King)','Tofu','Thai','Activation',106,10,5,6,'100g raw firm tofu||70g fresh ginger||50g wood ear mushrooms||30ml water||10ml natural fermented fish sauce||3g garlic||5g scallions','Julienne fresh ginger and slice wood ear mushrooms.||Sauté minced garlic and ginger in a non-stick pan with a splash of water until aromatic.||Add cubed firm tofu and stir-fry until golden on the edges.||Toss in wood ear mushrooms, natural fermented fish sauce, and remaining water, simmering for 3 minutes until tender.||Garnish with fresh scallions and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(69,'Tofu Jungle Curry (Gaeng Pa)','Tofu','Thai','Activation',107,10,6,7,'100g raw firm tofu||60g eggplant||50g green beans||50ml water||10ml natural fermented fish sauce||5g traditional Thai red curry paste||3g galangal||3g kaffir lime leaves','Dissolve traditional Thai red curry paste in a non-stick pan with a splash of water, simmering until fragrant.||Add diced eggplant and sliced green beans to the pan along with remaining water, galangal, and kaffir lime leaves.||Simmer uncovered for 10 minutes until the vegetables are tender.||Add cubed firm tofu during the final 3 minutes, simmering until heated through, then serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(70,'Tofu with Curry Paste and Long Beans (Prik King)','Tofu','Thai','Activation',105,10,5,6,'100g raw firm tofu||90g green beans||30ml water||10ml natural fermented fish sauce||6g traditional Thai red curry paste||3g kaffir lime leaves','Dry-sauté traditional Thai red curry paste in a non-stick pan with a splash of water until vibrant and aromatic.||Add sliced green beans, natural fermented fish sauce, and remaining water, simmering for 4 minutes until tender-crisp.||Add cubed firm tofu to the pan and toss for 2 minutes until coated in the reduced glaze.||Garnish with finely shredded kaffir lime leaves and serve warm.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(71,'Steamed Tofu with Glass Noodles (Ob Woonsen)','Tofu','Thai','Activation',103,10,5,5,'100g raw firm tofu||80g napa cabbage||40g celery||40ml water||10ml natural fermented fish sauce||3g fresh ginger||2g garlic','Arrange chopped napa cabbage and sliced celery at the bottom of a non-stick pot with a splash of water, minced garlic, and ginger.||Place cubed firm tofu on top of the vegetables.||Drizzle with natural fermented fish sauce, cover tightly, and steam-braise on medium heat for 6 minutes until the tofu is tender and infused with aromatics.||Serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(72,'Chicken and Cabbage Larb Slaw','Chicken','Thai','Activation',195,24,3,9,'100g chicken breast (finely minced)||70g white cabbage (finely shredded)||30g English cucumber (sliced into thin ribbons)||1 small shallot (thinly sliced)||1 small red bird''s eye chili (finely chopped)||Handful of fresh mint and coriander leaves||Dressing: 1.5 tbsp fresh lime juice, 1 tsp fish sauce, 1 tbsp water','Mix the raw minced chicken with 1/2 tbsp lime juice and 1 tbsp water (pre-acidifies the meat, keeping it tender without oil).||Heat a non-stick pan over medium-high heat. Add the chicken and the white parts of the sliced shallots.||Cook 5-6 minutes, breaking the chicken into a fine crumble until fully cooked. Remove and cool 2 minutes.||Toss the shredded cabbage, cucumber ribbons, chili, remaining shallot tops, mint and coriander in a bowl.||Pour the remaining lime juice and fish sauce over, add the warm chicken, toss well. Serve in a bowl or in lettuce leaves.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(73,'Chicken over Red Pepper and Broccoli Purees','Chicken','Western','Activation',240,34,4,12,'100g raw chicken breast||250g red bell pepper||100g broccoli||2g garlic||30ml lemon juice||2g smoked paprika||1g chili flakes||2g salt||1g white pepper','Cook the chicken your preferred way with spices of choice, rest, then slice.||RED PURÉE: dry-pan or water-sauté sliced red peppers with a lid on low heat 8-10 min until fully soft, letting some browning happen for depth.||Add half the garlic the last 2 min, then blend peppers with half the lemon juice, salt, and paprika, adding a splash of water until smooth; sieve for silk.||GREEN PURÉE: steam or boil broccoli until very soft, then blend with remaining garlic, remaining lemon juice, salt, and white pepper, adding a splash of water until smooth.||PLATE: spoon each purée on opposite sides of the plate and drag a spoon through for the swoosh.||Fan the sliced chicken across the middle, crack black pepper, and add herbs if you like.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(74,'Chicken and Cabbage Larb Slaw','Chicken','Thai','Activation',195,24,3,9,'100g chicken breast (finely minced)|70g white cabbage (finely shredded)|30g English cucumber (sliced into thin ribbons)|1 small shallot (thinly sliced)|1 small red bird''s eye chili (finely chopped)|Handful of fresh mint and coriander leaves|Dressing: 1.5 tbsp fresh lime juice, 1 tsp fish sauce, 1 tbsp water','In a small bowl, mix the raw minced chicken with 1/2 tbsp of the lime juice and 1 tbsp of water. (Chef''s secret: This pre-acidifies the meat, keeping it tender without oil).||Heat a non-stick pan over medium-high heat. Add the chicken and the white, sturdy parts of the sliced shallots.||Cook for 5–6 minutes, breaking the chicken up into a very fine crumble with a wooden spoon until completely cooked through. Remove from heat and let cool for 2 minutes.||In a large bowl, toss the shredded cabbage, cucumber ribbons, chili, the remaining shallot tops, mint, and coriander.||Pour the remaining lime juice and fish sauce over the vegetables, add the slightly cooled warm chicken, and toss vigorously. Serve immediately in a bowl or piled inside raw lettuce leaves.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(75,'Fish in Tomato and Vegetable Stew','Fish','Mediterranean','Activation',150,22,2,9,'100g white fish fillet (cod or tilapia)|70g canned chopped tomatoes (no added sugar/oil)|30g bell pepper (diced)|20g fresh spinach|1 clove garlic (minced)|Seasonings: 1/2 tsp dried oregano, a pinch of paprika, red chili flakes, 1/2 tsp fish sauce (Chef’s secret: simulates anchovy depth), a few fresh basil leaves','Heat a deep non-stick pan over medium heat. Add the chopped tomatoes, diced bell pepper, minced garlic, oregano, paprika, chili flakes, and fish sauce.||Simmer gently for 8–10 minutes, stirring occasionally, until the liquid reduces and the tomatoes become a thick, jammy paste.||Stir the fresh spinach into the tomato sauce until it wilts completely.||Pat the fish fillet completely dry with a paper towel. Nestle the fish directly into the center of the stew.||Cover the pan tightly with a lid, turn the heat down to low, and poach for 6–8 minutes until the fish is opaque and flakes easily with a fork. Top with fresh basil before serving.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(76,'Sichuan Chicken and Cabbage','Chicken','Sichuan (Chinese)','Activation',190,24,3,8,'100g chicken breast (sliced paper-thin across the grain)|100g white cabbage (cut into large 1-inch chunks)|1 clove garlic (minced)|Sichuan Sauce: 200ml chicken broth, 1 tsp light soy sauce, 1 tsp unsweetened rice vinegar, 1/2 tsp whole Sichuan peppercorns, 1/2 tsp crushed chili flakes','Heat a dry non-stick pan over medium-high heat. Toss in the whole Sichuan peppercorns and toast dry for 60 seconds until highly fragrant. Remove them, crush into a powder, and set aside.||In the same pan, pour the chicken broth, soy sauce, rice vinegar, minced garlic, chili flakes, and half of your crushed Sichuan pepper. Bring to a rolling boil.||Drop the paper-thin chicken slices into the boiling broth. Immediately turn off the heat completely, cover the pan with a lid, and let it sit undisturbed for 3–4 minutes. (Chef''s secret: This residual heat poaching prevents fat-free chicken from drying out). Remove the tender chicken with a slotted spoon and set aside.||Turn the heat back to medium-high. Throw the chunked cabbage into the remaining broth. Simmer for 3–4 minutes until the cabbage wilts and absorbs the dark broth.||Once the liquid has reduced down to a light, clingy syrup, return the chicken to the pan. Toss everything vigorously on high heat for 30 seconds. Dust with the remaining Sichuan pepper powder and serve.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(77,'Ginger-Scallion Chicken over Smashed Slaw','Chicken','Chinese','Activation',190,24,3,6,'100g chicken breast (whole)|70g English cucumber|30g white cabbage (finely shredded)|2 thick slices of fresh ginger + 1 big stalk of scallion (for poaching water)|Zero-Fat Relish: 1 tbsp finely minced fresh ginger, 1 stalk scallion (finely minced), 1/2 clove garlic (grated), 2 tbsp boiling chicken poaching broth, a pinch of salt, 1 tsp rice vinegar','In a small deep pot, submerge the chicken breast in water along with the ginger slices and scallion stalk. Bring to a gentle simmer, cover, and cook for 10 minutes until cooked through. Remove the chicken to rest, but keep the broth hot.||Place the cucumber on a cutting board. Use the flat side of a heavy knife or a rolling pin to smash it until it splits open. Slice it into bite-sized chunks, place in a colander, toss with a tiny pinch of salt, and let drain for 5 minutes. Discard the extracted water.||Mix the drained smashed cucumber with the shredded cabbage and toss with 1 tsp of rice vinegar. Lay this base on your serving plate.||Make the relish: In a small heatproof bowl, mix the minced ginger, minced scallion, grated garlic, and salt. Ladle 2 tbsp of the boiling hot chicken poaching broth directly over the aromatics to "bloom" them without oil.||Slice the chicken breast thinly, arrange it over the top of the cucumber-cabbage slaw, and spoon the warm ginger-scallion relish generously over the meat.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(78,'Loaded Egg-White Frittata','Egg','Mediterranean','Activation',130,22,1,6,'180g liquid egg whites|50g cremini mushrooms (sliced)|30g bell pepper (diced)|20g fresh spinach (chopped)|Seasonings: 1/2 tsp dried oregano, chili flakes, garlic powder, salt, and pepper','Preheat your oven to 190°C (375°F). Line a small cake pan or oven-safe skillet with parchment paper (Chef''s secret: guarantees a non-stick release without spray or oil).||Heat a non-stick pan over medium heat. Toss in the mushrooms and bell peppers with 1 tbsp of water. Sauté for 3–4 minutes until tender. Stir in the chopped spinach for 30 seconds until wilted, then remove from heat.||In a medium bowl, pour the liquid egg whites. Add the oregano, chili flakes, garlic powder, salt, and pepper. Use a fork to whip the whites vigorously for 30 seconds until slightly frothy. (This traps air, giving the fat-free frittata a lighter, fluffy rise).||Stir the cooked vegetables into the seasoned egg whites.||Pour the mixture into your parchment-lined baking dish. Bake in the oven for 15 minutes until puffed up, golden on the edges, and firmly set in the center.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(79,'Prawn, Bok Choy and Mushroom Broth','Prawn','Chinese','Activation',145,22,2,8,'100g raw prawns (peeled and deveined)|70g bok choy (halved lengthwise, separating green leafy tops from white stalks)|40g cremini mushrooms (sliced)|1 spring onion/scallion (finely sliced)|Broth Base: 400ml low-sodium chicken or vegetable broth, 1 clove garlic (grated), 1 tsp fresh ginger (grated), 1 tsp light soy sauce, a pinch of white pepper, chili flakes to taste','In a small pot, combine the 400ml broth, grated garlic, grated ginger, soy sauce, and white pepper. Bring to a gentle simmer for 4 minutes to infuse the liquids.||Add the sliced mushrooms and the sturdy, white bottom stalks of the bok choy. Simmer for 2 minutes.||Drop in the raw prawns and the green leafy tops of the bok choy. Cook for exactly 60–90 seconds until the prawns turn completely pink and opaque.||Turn off the heat, ladle into a large soup bowl, and garnish with fresh scallion and chili flakes.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(80,'Prawn and Vegetable Chawanmushi','Prawn','Japanese / Clean','Activation',140,25,1,4,'4-egg-whites||235ml warm water mixed with 1/2 tsp light soy sauce and a tiny pinch of white pepper|40g raw prawns (finely chopped)|60g cremini mushrooms (finely chopped)|30g spinach (finely chopped)|1 spring onion/scallion (finely sliced)','Arrange the chopped prawns, mushrooms, and spinach evenly across the bottom of a heatproof ceramic bowl or ramekin.||In a separate bowl, gently whisk the liquid egg whites with the seasoned warm water/soy mixture until completely combined. Try not to create too many air bubbles.||Strain the egg mixture through a fine-mesh sieve directly into the bowl over your vegetables and prawns.||Cover the top of the bowl tightly with aluminium foil to block condensation water drops.||Set up a steamer basket over a pot of gently simmering water (not a rolling boil). Place the foiled bowl inside, cover with the pot lid, and steam on low heat for 12–14 minutes until the center is just set like a delicate custard. Top with scallions.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(81,'Squid, Cucumber and Pepper Salad','Squid','Thai','Activation',135,19,1.5,7,'100g squid tubes (cleaned)|60g English cucumber (sliced)|40g bell pepper (thinly sliced)|Handful of fresh coriander leaves|1 clove garlic (minced)|Dressing: 1 tbsp fresh lime juice, 1 tsp fish sauce, 1 small chopped red chili, 1 tbsp water','Prepare an ice bath (a bowl filled with cold water and ice cubes) and set it aside.||Lay the squid tube flat on a cutting board. Cut it open, and score the inside surface in a tight, diagonal diamond cross-hatch pattern with a sharp knife. Slice into bite-sized squares.||Bring a small pot of water to a rolling boil. Drop the squid pieces in for exactly 45 seconds. They will instantly curl up into textured shapes.||Immediately scoop the squid out and plunge it into the ice bath to stop the cooking process completely. (Chef''s secret: This ensures the squid stays incredibly tender and snappy, never chewy). Drain well.||In a medium bowl, whisk the lime juice, fish sauce, minced garlic, chili, and water together. Add the cucumber, bell pepper, chilled squid, and coriander. Toss thoroughly so the dressing catches in the scored grooves of the squid.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(82,'Baked Fish on Peperonata','Fish','Mediterranean','Activation',150,22,2,10,'100g tilapia or cod fillet|60g bell pepper (thinly sliced into strips)|40g fresh tomato (diced)|20g onion (thinly sliced)|1 clove garlic (minced)|Seasonings: 1/2 tsp dried oregano, a pinch of sweet paprika, chili flakes, salt, and pepper','Heat a non-stick pan over medium heat. Add the sliced onion, garlic, and 2 tablespoons of water. Water-sauté for 3 minutes until the onions soften.||Add the bell pepper strips, diced tomatoes, oregano, paprika, and chili flakes. Reduce heat to low, cover, and let the vegetables sweat in their own juices for 7–8 minutes until completely soft, sweet, and jammy (peperonata).||Pat your fish fillet dry and season lightly with salt and pepper.||Push the sweet peppers slightly aside, lay the fish fillet directly onto the bottom of the pan, and spoon some of the jammy tomato-pepper mixture over the top of the fish.||Cover tightly, turn the heat to medium-low, and steam-cook for 6–8 minutes until the fish flakes beautifully.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(83,'Garlic-Ginger Prawn and Broccoli','Prawn','Chinese','Activation',155,23,2,10,'100g raw prawns (peeled and deveined)|100g broccoli (cut into small bite-sized florets)|1 clove garlic (minced)|1 tsp fresh ginger (minced)|Stir-Cote Liquid: 100ml chicken broth, 1 tsp light soy sauce, red chili flakes','Place the broccoli florets into a steamer basket over boiling water. Steam for exactly 3–4 minutes until they turn a vibrant, brilliant green but still retain a crisp bite. Set aside.||In a wide non-stick pan or wok over medium-high heat, combine the 100ml chicken broth, minced garlic, minced ginger, soy sauce, and chili flakes. Bring to a vigorous boil and let it bubble for 60 seconds to concentrate the flavors.||Toss the steamed broccoli into the bubbling sauce. Because broccoli acts like a sponge, toss it rapidly for 30 seconds so the florets drink up the hot garlic-ginger broth.||Drop the raw prawns directly into the pan. Toss continuously for about 90 seconds.||As soon as the prawns curl tightly and turn pink, and the remaining liquid reduces down to a thin glaze that clings to the food, pull the pan off the heat and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(84,'Garlic Butter Salmon and Asparagus','Fish','American','Stabilization',380,34,26,4,'150g raw salmon fillet||100g asparagus spears||15g unsalted butter||10g olive oil||2g minced garlic||5ml lemon juice||1g sea salt','Pat salmon dry and season with sea salt and garlic.||Heat olive oil in a skillet over medium-high heat and sear salmon skin-side down for 4 minutes.||Flip salmon, add butter and asparagus to the pan, and spoon melted butter over the fish.||Cook until asparagus is tender-crisp and salmon is cooked through.||Drizzle with lemon juice before serving.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(85,'Creamy Tuscan Garlic Chicken','Chicken','Mediterranean','Stabilization',420,38,28,5,'120g raw chicken thigh||40g baby spinach||30g heavy cream||15g sun-dried tomatoes||10g grated parmesan cheese||10g olive oil||2g garlic','Brown chicken thighs in a skillet with olive oil until golden brown on both sides.||Remove chicken and sauté garlic and sun-dried tomatoes in the remaining pan juices.||Stir in heavy cream and parmesan cheese until a smooth sauce forms.||Return chicken to the pan, fold in baby spinach, and simmer until spinach is wilted and chicken is cooked.||Serve warm with the creamy sauce poured over top.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(86,'Beef and Broccoli Stir-Fry','Beef','Asian','Stabilization',340,32,20,6,'130g lean beef flank steak||120g broccoli florets||15g sesame oil||10ml coconut aminos||5g fresh grated ginger||2g garlic||5g sesame seeds','Slice beef thinly against the grain.||Heat sesame oil in a wok and sauté garlic and ginger until fragrant.||Add beef slices and stir-fry until browned.||Toss in broccoli florets and coconut aminos, covering the pan for 3 minutes to steam-cook the broccoli.||Garnish with sesame seeds and serve hot.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(87,'Lemon Herb Shrimp Zoodles','Seafood','Mediterranean','Stabilization',260,29,13,5,'140g raw peeled shrimp||120g zucchini noodles (zoodles)||(15g butter||10ml olive oil||10ml lemon juice||5g fresh dill||2g garlic','Melt half the butter and olive oil in a skillet over medium heat.||Add garlic and shrimp, cooking until pink and opaque (about 3 minutes), then remove shrimp.||Add remaining butter and zucchini noodles to the pan, tossing gently for 2 minutes until warm.||Return shrimp to the skillet, toss with fresh dill and lemon juice, and serve immediately.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(88,'Keto Cloud Bread','Egg','Low-carb','Stabilization',365,21,30,3,'3 large eggs (whites and yolks separated, room temperature)||45g full-fat cream cheese (softened)||1/2 tsp cream of tartar or 1/4 tsp vinegar||1/2 tsp salt (optional)','Preheat oven to 150C (300F) and line a baking sheet with parchment paper.||Whip the egg whites with the cream of tartar in a clean, grease-free bowl until stiff peaks form.||In a separate bowl, whisk the egg yolks, softened cream cheese, and salt until smooth and creamy.||Gently fold the yolk mixture into the whipped whites, keeping the foam airy.||Scoop about 1/4 cup portions onto the baking sheet as round mounds.||Bake 25 to 30 minutes until golden brown.||Cool completely on the sheet before removing.');
INSERT INTO "recipes" ("id","name","protein","cuisine","phase","kcal","protein_g","fat_g","carbs_g","ingredients","steps") VALUES(89,'Keto Carrot Tortillas','Cheese/Egg','Mexican','Stabilization',625,43,38,21,'250g grated carrots||125g shredded mozzarella||2 large eggs (beaten, ~100g)||1/2 tsp garlic powder||1/2 tsp dried oregano||salt and black pepper to taste||pinch of paprika (optional)||Toppings (not counted): guacamole, sliced chicken or ham, arugula, sour cream, salsa','Preheat oven to 190C (375F) and line a baking sheet with parchment or a silicone mat.||In a large bowl, mix the grated carrots, mozzarella, beaten eggs, garlic powder, oregano, salt and pepper until the carrots are fully coated.||Divide into 4 to 5 portions on the sheet and flatten each into a thin round tortilla with a spatula.||Bake 20 to 25 minutes until the edges are golden and the cheese has set.||Cool completely on the parchment for 5 to 10 minutes so the cheese firms and holds the wrap together.||Peel off gently, fill with taco toppings, fold or roll to serve.');
