INSERT INTO "policy" ("id","phase","rules_text") VALUES(1,'loading','Eat freely to a high calorie target. Almost everything is YES. NO only: added-sugar sweets/desserts/candy, sugary soft drinks, fruit juice, and alcohol.');
INSERT INTO "policy" ("id","phase","rules_text") VALUES(2,'activation','Protein-sparing modified fast. Judge per 100g raw. VEGETABLES: YES if net carbs <5g and sugar <5g and no added sugar/oil/starch; LIMITED if net carbs 5-15g or sugar 5-12g (e.g. onion, carrot, beetroot); NO if starchy (potato, corn, peas), any added sugar/oil/starch, or dried. FRUIT by sugar/100g: YES if sugar <12g (apple, orange, grapefruit, berries, lemon, lime, peach, plum); NO if sugar >=12g or dried (grape, banana, mango, pineapple, cherry). Never mark fruit LIMITED. PROTEIN by fat only: YES fat <5g; LIMITED fat 5-10g; NO fat >10g, or oily fish (salmon, tuna, mackerel, sardine), cured/processed (bacon, sausage, ham), pork, or skin-on dark meat. Tofu YES; tempeh LIMITED; egg whites YES; whole egg NO. Fried, breaded, oiled, sugared or junk/fast food = NO. Grains/starch (rice, bread, pasta, potato, noodles) = NO. Cheese, milk, whole egg = NO. Nuts, seeds, avocado, oils = NO. ZERO added oil or fat in cooking. Dark chocolate (≥70% cocoa): YES, max 20g per day. Apple: YES, max 2 per day');
INSERT INTO "policy" ("id","phase","rules_text") VALUES(3,'stabilization','Low-carb keto maintenance; weight already lost, hold it. Fat is allowed and is the main fuel; carbs and sugar are the watch-item. Judge per 100g raw. PROTEIN: all YES including fatty cuts, skin-on poultry, pork, plain bacon, whole eggs, oily fish, shellfish, tofu, tempeh. NO only if cured/glazed with added sugar (honey ham, sweet bacon) or breaded/battered. VEGETABLES: above-ground low-carb YES (leafy greens, broccoli, cauliflower, cabbage, zucchini, asparagus, celery, cucumber, eggplant, green beans, tomato, mushroom, bell pepper, onion/garlic in small amounts). LIMITED: carb-dense (carrot, beetroot, pumpkin). NO: starchy (potato, sweet potato, corn, peas), beans/legumes, added sugar, dried. FATS: YES (olive/avocado/coconut oil, butter, ghee, avocado, olives); LIMITED nuts, seeds. DAIRY: full-fat YES (hard/soft cheese, heavy cream, full-fat Greek yogurt); NO milk, sweetened or low-fat dairy. FRUIT by sugar/100g: YES if sugar ≤12.5g (berries, apple any kind, watermelon, peach, plum, grapefruit, orange, lemon, lime); LIMITED if sugar 12.6-13.5g; NO if sugar >13.5g, dried fruit, or fruit juice. NO added sugar, sweets, starch, grains, sugary or alcoholic drinks. Cooking in allowed fats is fine. Dark chocolate (≥70% cocoa): YES, max 20g per day. Apple: YES, max 2 per day.');
