INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('loading','Loading','#8a8a8a',10,2,'loading_days',1,1,0,0,0,0,'hidden',0,NULL,'Loading: eat freely to your target. Avoid only sweets, sugary drinks and alcohol.','{"sub":"The ramp-in","change":"Eat freely to a high target. This sets your body up. It is not the diet yet.","eat":"Almost all whole foods: protein, veg, fruit, grains, rice, potato, dairy.","avoid":"Added-sugar sweets and desserts, sugary drinks and juice, alcohol.","targets":["Eat to a high calorie target","No fasting window"],"expect":"Enjoy these two days. You are setting up, not restricting yet."}','Ease into movement. Gentle and short.',1,1,NULL,NULL,'none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'aevum');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('activation','Activation','#B08D2E',20,NULL,NULL,1,1,1,1,1,1,'protocol',0,NULL,'Grilled protein + vegetables. No rice, bread, noodles or potato. No oil, no sauce.','{"sub":"The core reset","change":"Very low calorie and protein-sparing. Your body burns through its quick sugar (glucose) and switches to running on your stored body fat (ketosis). That switch is the whole point.","eat":"Lean protein, low-carb veg, low-sugar fruit.","avoid":"Oil, fat, grains, starch, dairy and sugary foods.","targets":["{VLCD} kcal a day","16/8 fasting (8-hour eating window)","Water 2.5 L","Serum morning and evening"],"expect":"Days 2 to 4 can feel flat or foggy while your body changes fuel. It passes: energy steadies and hunger fades. That is the switch working."}','A little movement today. Pick something and follow along, no rush.',1,1,NULL,NULL,'fixed',400,650,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'aevum');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('transition','Transition','#B08D2E',30,3,'transition_days',1,0,1,1,1,1,'protocol',0,'activation','Grilled protein + vegetables. No rice, bread, noodles or potato. No oil, no sauce.','{"sub":"Easing out","change":"The serum stops here. These days settle your body at its new, lower weight before food widens. The rules stay the same as Activation.","eat":"Same as Activation: lean protein and low-carb veg.","avoid":"Same as Activation: no oil, fat, grains, starch, dairy or sugar.","targets":["{VLCD} kcal a day","16/8 fasting","Water 2.5 L","No serum"],"expect":"You are easing out, letting your body get comfortable where it is now. Nearly through the strict block."}','A little movement today. Pick something and follow along, no rush.',1,1,NULL,NULL,'fixed',400,650,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'aevum');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('stabilization','Stabilization','#4a463f',40,18,'stabilization_days',1,0,0,0,1,0,'bar',0,NULL,'Stabilization: protein + fat + low-carb veg. Berries only. No sugar, starch, grains or added-sugar foods.','{"sub":"Locking the new set-point","change":"More food, fats come back, calories climb back up. But this is not a finish line.","eat":"All protein, low-carb veg, healthy fats, full-fat dairy, berries.","avoid":"Sugar, grains, starch and most fruit.","targets":["Calories ramp up over 4 days to about 90% of maintenance, then hold","Carbs under 40 g a day, from veg","Protein 1.2 to 1.5 g per kg","Weight held within 500 g"],"expect":"You can eat more, but you are not out of the woods. Keep sugar and carbs out or the weight rebounds fast. Hold the line and the new set-point locks in. Energy returns and weight settles."}','Pick a routine and follow along at your own pace.',1,1,0.9,'{"protein":{"unit":"g_per_kg","min":1.2,"max":1.5,"amber_low":1.0,"red_low":0.8},"fat":{"unit":"gated"},"carbs":{"unit":"gated"},"water":{"unit":"free"}}','ramp_then_hold',NULL,NULL,600,4,'[0, 0.35, 0.60, 0.80, 1.0]',NULL,NULL,NULL,1,7,150,1200,0.5,'aevum');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('maintenance','Maintenance','#3E7A6A',50,NULL,NULL,1,0,0,0,1,0,'bar',1,NULL,'Maintenance: balanced meals, protein first. Keep carbs moderate. Track calories to stay on target.','{"sub":"Your new normal","change":"The program is done. Now you keep going on your own with the tracker, adaptive calories and the AI meal analyser.","eat":"Balanced meals: protein first, healthy fats, moderate carbs. Same principles, more freedom.","avoid":"Excess sugar, ultra-processed food, large calorie spikes.","targets":["Adaptive calorie target (TDEE x 0.90)","Protein 1.2 g per kg","Carbs moderate, from whole foods","Calorie bank: 4-day rolling balance"],"expect":"Weight may fluctuate day to day. Focus on the trend. The calorie bank gives you flexibility across days."}','Keep moving. Pick a routine that fits your day.',1,1,0.95,'{"protein":{"unit":"g_per_kg","min":1.2,"max":1.5,"amber_low":1.0,"red_low":0.8},"fat":{"unit":"free"},"carbs":{"unit":"free"},"water":{"unit":"free"}}','tdee_mult',NULL,NULL,NULL,NULL,NULL,4,0.85,1.15,1,7,150,1200,0.5,'maintenance');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('tracker','Tracking','#3E7A6A',60,NULL,NULL,0,0,0,0,1,0,'bar',1,NULL,'Track your meals and stay on target.','{"sub":"Your daily tracker","change":"Track calories, macros and weight to stay on course.","eat":"Balanced meals: protein first, healthy fats, moderate carbs.","avoid":"Excess sugar, ultra-processed food.","targets":["Calorie target based on your TDEE","Protein 1.2 g per kg"],"expect":"Consistency is the goal. Track daily and watch the trend."}','Keep moving. Pick a routine that fits your day.',0,0,1,'{"protein":{"unit":"g_per_kg","min":1.2,"max":1.5,"amber_low":1.0,"red_low":0.8},"fat":{"unit":"free"},"carbs":{"unit":"free"},"water":{"unit":"free"}}','tdee_mult',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,NULL,NULL,NULL,NULL,'tracking');
INSERT INTO "phases" ("key","name","color","sort_order","duration_default","duration_col","is_program","requires_serum","has_fasting","gate_fat","gate_carb","use_buckets","calorie_mode","calorie_bank","inherits_rules_from","food_rule_line","explainer_json","fitness_intro","show_in_phase_bar","show_in_recipe_chips","calorie_cut","macro_rules","target_mode","target_fixed_lo","target_fixed_hi","ramp_from","ramp_days","ramp_pct","bank_window","bank_clamp_lo","bank_clamp_hi","drift_enabled","drift_review_days","drift_step_kcal","drift_floor_kcal","drift_band_kg","program_id") VALUES('recomposition','Recomposition','#5B738A',55,NULL,NULL,1,0,0,1,0,0,'bar',1,NULL,'Recomposition: high protein, moderate fat, carbs fill the rest. Train hard, recover well.','{"sub":"Building lean mass","change":"Same calorie target as maintenance but with a higher protein floor and structured fat minimum. The goal shifts from weight loss to body composition: less fat, more muscle.","eat":"High-protein meals: lean meat, fish, eggs, dairy. Healthy fats at every meal. Carbs from whole foods around training.","avoid":"Empty calories, excess sugar, ultra-processed food. Do not cut fat below 0.8 g per kg.","targets":["Calories: TDEE x 0.90 (10% deficit)","Protein: 2 g per kg bodyweight","Fat: 0.8 to 1 g per kg (never below 0.8)","Carbs: remaining calories after protein and fat","Water: 0.04 L per kg + 0.5 L per training hour","Creatine: 5 g per day, every day"],"expect":"Weight may stay flat or rise slightly as muscle builds. Track measurements and how clothes fit, not just the scale. Strength should climb steadily."}','Train with intent. Progressive overload is the driver.',1,1,0.9,'{"protein":{"unit":"g_per_kg","min":1.9,"max":2.0,"amber_low":1.6,"red_low":1.2},"fat":{"unit":"g_per_kg","min":0.8,"max":1.0,"amber_low":0.6,"red_low":0.4,"amber_high":1.2,"red_high":1.5},"carbs":{"unit":"free"},"water":{"unit":"l_per_kg","target":0.04}}','tdee_mult',NULL,NULL,NULL,NULL,NULL,4,0.85,1.15,1,7,150,1200,0.5,'recomposition');
