PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE auth_tokens (
  token       TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL,
  role        TEXT NOT NULL DEFAULT 'user',  -- 'user' or 'admin'
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at  TEXT,                           -- NULL = never expires
  UNIQUE(user_id, role)
);
CREATE TABLE users (
  id                    TEXT PRIMARY KEY,
  name                  TEXT NOT NULL,
  sex                   TEXT CHECK(sex IN ('m','f')),
  age                   INTEGER,
  height                REAL,
  start_weight          REAL,
  activity              REAL DEFAULT 1.55,
  target_kg             REAL,
  start_date            TEXT,
  activation_days       REAL,
  activation_model      TEXT DEFAULT 'buckets',
  stab_target_weight    REAL,
  maint_target_weight   REAL,
  current_target_kcal   REAL,
  prev_target_kcal      REAL,
  last_review_date      TEXT,
  last_change_reason    TEXT,
  maintenance_mode      TEXT,
  maintenance_diet      TEXT,
  program               INTEGER DEFAULT 0,   -- 0=free, 1=program client
  notes                 TEXT,
  email                 TEXT,
  created_at            TEXT NOT NULL DEFAULT (datetime('now'))
, dob TEXT, intake_token TEXT DEFAULT NULL, loading_days INTEGER, transition_days INTEGER, stabilization_days INTEGER, phase_mode TEXT, program_id TEXT DEFAULT 'aevum', program_start_date TEXT);
CREATE TABLE meal_plans (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id   TEXT NOT NULL,
  day       INTEGER NOT NULL,
  meal      TEXT,
  recipe    TEXT,
  kcal      REAL DEFAULT 0,
  protein   REAL DEFAULT 0,
  fat       REAL DEFAULT 0,
  carbs     REAL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, meal_type TEXT DEFAULT 'recipe', meal_slot TEXT DEFAULT '', components_json TEXT DEFAULT '');
CREATE TABLE recipes (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT NOT NULL,
  protein     TEXT,
  cuisine     TEXT,
  phase       TEXT,
  kcal        REAL DEFAULT 0,
  protein_g   REAL DEFAULT 0,
  fat_g       REAL DEFAULT 0,
  carbs_g     REAL DEFAULT 0,
  ingredients TEXT,    -- stored as || separated
  steps       TEXT     -- stored as || separated
);
CREATE TABLE messages (
  id        TEXT PRIMARY KEY,
  trigger   TEXT NOT NULL,
  enabled   TEXT DEFAULT 'yes',
  phase     TEXT,
  priority  INTEGER DEFAULT 0,
  title     TEXT,
  body      TEXT,
  badge     TEXT,
  frequency TEXT DEFAULT 'daily'
);
CREATE TABLE movements (
  id        TEXT PRIMARY KEY,
  name      TEXT NOT NULL,
  phase     TEXT,
  equipment TEXT,
  video_url TEXT,
  cues      TEXT,     -- || separated
  mistake   TEXT
);
CREATE TABLE workouts (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  workout_id    TEXT NOT NULL,
  workout_name  TEXT,
  phase         TEXT,
  duration_min  INTEGER,
  sort_order    INTEGER,
  movement_id   TEXT,
  sets          INTEGER,
  reps          INTEGER,
  rest_sec      INTEGER
);
CREATE TABLE rules (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  phase     TEXT NOT NULL,
  model     TEXT DEFAULT 'all',
  metric    TEXT NOT NULL,
  basis     TEXT DEFAULT 'fixed',
  value     REAL,
  green_lo  REAL,
  green_hi  REAL,
  amber_lo  REAL,
  amber_hi  REAL,
  gated     TEXT DEFAULT 'yes',
  unit      TEXT
);
CREATE TABLE foods (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  phase       TEXT NOT NULL,
  category    TEXT,
  subcategory TEXT,
  item        TEXT NOT NULL,
  verdict     TEXT DEFAULT 'yes',
  cap_g       REAL,
  note        TEXT
);
CREATE TABLE policy (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  phase       TEXT NOT NULL UNIQUE,
  rules_text  TEXT NOT NULL
);
CREATE TABLE config (
  key   TEXT PRIMARY KEY,
  value TEXT
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE ingredients (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  per_100g_kcal REAL DEFAULT 0,
  per_100g_p REAL DEFAULT 0,
  per_100g_f REAL DEFAULT 0,
  per_100g_c REAL DEFAULT 0,
  source TEXT DEFAULT 'manual'
);
CREATE TABLE catered_menu (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL,
  name TEXT NOT NULL,
  per_serving_kcal REAL DEFAULT 0,
  per_serving_p REAL DEFAULT 0,
  per_serving_f REAL DEFAULT 0,
  per_serving_c REAL DEFAULT 0,
  serving_g REAL DEFAULT 0
);
CREATE TABLE intake_tokens (token TEXT PRIMARY KEY, client_name TEXT NOT NULL, prefill_json TEXT NOT NULL DEFAULT '{}', response_json TEXT DEFAULT NULL, current_step INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL DEFAULT (datetime('now')), expires_at TEXT NOT NULL DEFAULT (datetime('now', '+14 days')), submitted_at TEXT DEFAULT NULL);
CREATE TABLE body_scans (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  scan_date TEXT NOT NULL,
  scan_type TEXT NOT NULL DEFAULT 'InBody',
  scan_weight REAL,
  scan_bmi REAL,
  body_fat_pct REAL,
  fat_mass REAL,
  smm REAL,
  tbw REAL,
  scan_bmr INTEGER,
  visceral_fat REAL,
  body_score REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')), scan_height REAL, reference_json TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE phases (
  key                TEXT PRIMARY KEY,
  name               TEXT NOT NULL,
  color              TEXT NOT NULL,
  sort_order         INTEGER NOT NULL,
  duration_default   INTEGER,          -- NULL = open-ended
  duration_col       TEXT,             -- users column for per-user override
  is_program         INTEGER DEFAULT 1,
  requires_serum     INTEGER DEFAULT 0,
  has_fasting        INTEGER DEFAULT 0,
  gate_fat           INTEGER DEFAULT 0,
  gate_carb          INTEGER DEFAULT 0,
  use_buckets        INTEGER DEFAULT 0,
  calorie_mode       TEXT DEFAULT 'bar',   -- 'bar', 'protocol', 'hidden'
  calorie_bank       INTEGER DEFAULT 0,
  inherits_rules_from TEXT,
  food_rule_line     TEXT,
  explainer_json     TEXT,
  fitness_intro      TEXT,
  show_in_phase_bar  INTEGER DEFAULT 1,
  show_in_recipe_chips INTEGER DEFAULT 1
, calorie_cut REAL, macro_rules TEXT, target_mode TEXT DEFAULT 'none', target_fixed_lo REAL, target_fixed_hi REAL, ramp_from REAL, ramp_days INTEGER, ramp_pct TEXT, bank_window INTEGER, bank_clamp_lo REAL, bank_clamp_hi REAL, drift_enabled INTEGER DEFAULT 0, drift_review_days INTEGER, drift_step_kcal REAL, drift_floor_kcal REAL, drift_band_kg REAL, program_id TEXT DEFAULT 'aevum');
CREATE TABLE phase_transitions (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    TEXT NOT NULL,
  from_phase TEXT NOT NULL,
  to_phase   TEXT NOT NULL,
  day        INTEGER NOT NULL,
  date       TEXT NOT NULL,
  reason     TEXT
);
CREATE TABLE orders (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'draft',
  delivery_date TEXT,
  total_kcal    INTEGER,
  notes         TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE order_items (
  id              TEXT PRIMARY KEY,
  order_id        TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  menu_item_id    TEXT,
  name            TEXT NOT NULL,
  quantity        INTEGER NOT NULL DEFAULT 1,
  kcal            INTEGER,
  protein         REAL,
  fat             REAL,
  carbs           REAL,
  customizations  TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE user_config (
  user_id    TEXT NOT NULL,
  key        TEXT NOT NULL,
  value      TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, key)
);
CREATE TABLE programs (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  description TEXT,
  color       TEXT DEFAULT '#3E7A6A',
  sort_order  INTEGER DEFAULT 0,
  is_active   INTEGER DEFAULT 1
);
CREATE TABLE program_transitions (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id       TEXT NOT NULL,
  from_program  TEXT,
  to_program    TEXT NOT NULL,
  from_phase    TEXT,
  to_phase      TEXT,
  switched_at   TEXT NOT NULL,
  notes         TEXT
);
CREATE TABLE IF NOT EXISTS "daily_logs" (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   user_id       TEXT NOT NULL,   day           INTEGER NOT NULL,   phase         TEXT,   date          TEXT NOT NULL,   weight        REAL,   waist         REAL,   serum_am      TEXT,   serum_pm      TEXT,   kcal          REAL,   protein       REAL,   fat           REAL,   carbs         REAL,   water_ml      REAL,   exercise      TEXT,   exercise_kcal REAL,   energy        TEXT,   hunger        TEXT,   sleep         TEXT,   notes         TEXT,   day_json      TEXT,   created_at    TEXT NOT NULL DEFAULT (datetime('now')),   updated_at    TEXT NOT NULL DEFAULT (datetime('now')),   UNIQUE(user_id, date) );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_meal_plans_user    ON meal_plans(user_id);
CREATE INDEX idx_auth_tokens_user   ON auth_tokens(user_id);
CREATE INDEX idx_rules_phase        ON rules(phase, metric);
CREATE INDEX idx_foods_phase        ON foods(phase);
CREATE INDEX idx_workouts_id        ON workouts(workout_id);
CREATE INDEX idx_intake_status ON intake_tokens(status, created_at);
CREATE INDEX idx_users_intake_token ON users(intake_token);
CREATE INDEX idx_body_scans_user ON body_scans(user_id, scan_date);
CREATE INDEX idx_phase_transitions_user ON phase_transitions(user_id);
CREATE INDEX idx_meal_plans_user_day ON meal_plans(user_id, day);
CREATE INDEX idx_rules_phase_metric ON rules(phase, metric);
CREATE INDEX idx_orders_user ON orders(user_id);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_program_transitions_user ON program_transitions(user_id);
CREATE INDEX idx_program_transitions_date ON program_transitions(user_id, switched_at);
CREATE INDEX idx_daily_logs_user_date ON daily_logs(user_id, date);
